// Records a captioned video of the Validation Protocol Generator report reset:
// the on-screen disclaimer, a real PDF generated by the real /api/generate-protocol
// and /api/vpg-engines code, and a look at the pages that changed.
// Usage (server must be on port 3000, see server.js):
//   node server.js ../.. 3000 &
//   node record-vpg.js http://localhost:3000 ./video-vpg [chromePath]
const { chromium } = require("playwright");
const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const base = process.argv[2];
const out = path.resolve(process.argv[3]);
const exe = process.argv[4];

// A made-up but realistic deployment: an ED sepsis alert at a safety-net hospital.
const ANSWERS = {
  q0: "primary", q0b: "full",
  q1_orgname: "Example County Medical Center", q1_dept: "Emergency Department",
  q1_system: "Example Sepsis Alert", q1_vendor: "Example Vendor Inc.", q1_version: "4.2",
  q2_usetype: "Triage / prioritization — direct impact on care sequencing",
  q30_age: "Predominantly adult (18–65)",
  q31_sex_record: "Binary with unknown / not recorded option",
  q32_race_record: "Combined race/ethnicity field",
  q35_payer: "Safety net — predominantly Medicaid / uninsured",
  q38_setting: "Emergency department",
  q3_prevalence: "5 — 15%",
  q7_cases: "Yes — accessible and ready",
  Q15: "78", Q16: "84",
  q19_cadence: "Monthly",
  q19_owner: "Named individual by role",
  q15a_authority: "Named individual by role", q15a_authority_role: "CMIO",
  q15_gap_time: "Within 4 hours",
  q22_warn_threshold: "5%", q23_action_threshold: "10%",
};

(async () => {
  fs.mkdirSync(out, { recursive: true });
  const browser = await chromium.launch(exe ? { executablePath: exe } : {});
  // Video is stitched from one screenshot per caption (Playwright's own recorder needs a
  // matching ffmpeg build, which isn't always available). Needs ffmpeg on PATH.
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, acceptDownloads: true });
  const frames = [];
  // jsPDF normally comes from cdnjs; serve the same version locally so the test runs offline
  await ctx.route("**/jspdf.umd.min.js", r => r.fulfill({ path: require.resolve("jspdf/dist/jspdf.umd.min.js"), contentType: "text/javascript" }));
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));

  const caption = async (text, ms = 2600) => {
    await page.evaluate(t => {
      let el = document.getElementById("__cap");
      if (!el) {
        el = document.createElement("div");
        el.id = "__cap";
        el.style.cssText = "position:fixed;left:0;right:0;bottom:0;z-index:99999;padding:14px 22px;background:rgba(10,12,20,.94);color:#f5f0ff;font:600 17px/1.4 system-ui,sans-serif;border-top:2px solid #a78bfa";
        document.body.appendChild(el);
      }
      el.textContent = t;
    }, text);
    const shot = path.join(out, `frame-${String(frames.length).padStart(3, "0")}.png`);
    await page.screenshot({ path: shot });
    frames.push({ shot, sec: ms / 1000 });
  };

  await page.goto(`${base}/validation-protocol/`);
  await page.waitForTimeout(1000);
  await caption("Validation Protocol Generator · test run with a made-up ED sepsis alert at a safety-net hospital");
  await page.evaluate(a => { Object.assign(state.answers, a); goToReady(); }, ANSWERS);
  await page.waitForTimeout(600);
  await caption("Answers filled in. This is the last screen before the PDF.", 2000);

  const disc = page.locator(".commons-disclaimer");
  await disc.scrollIntoViewIfNeeded();
  await disc.evaluate(el => { el.style.outline = "3px solid #a78bfa"; el.style.outlineOffset = "4px"; });
  await caption("New: the shared disclaimer, right above the button. Same wording will go on every report tool.", 4200);
  await caption("This tool uses no AI to write the report, so it says that instead of 'parts are AI-generated'.", 3600);

  const dl = page.waitForEvent("download");
  await page.locator("#generate-btn").click();
  await caption("Generating with the real protocol code…", 1500);
  const file = path.join(out, "vpg-test.pdf");
  await (await dl).saveAs(file);
  await page.waitForTimeout(800);
  await caption("PDF downloaded. Now the pages that changed.", 1800);

  // Render the PDF pages and walk through them
  execFileSync("pdftoppm", ["-png", "-r", "70", file, path.join(out, "pg")]);
  const pngs = fs.readdirSync(out).filter(f => /^pg-\d+\.png$/.test(f)).sort();
  const img = n => "data:image/png;base64," + fs.readFileSync(path.join(out, pngs[n - 1])).toString("base64");
  const find = text => {
    for (let i = 1; i <= pngs.length; i++) {
      const t = execFileSync("pdftotext", ["-f", String(i), "-l", String(i), file, "-"]).toString();
      if (t.includes(text)) return i;
    }
    return 1;
  };
  const show = async (n, text, ms = 4200) => {
    await page.setContent(`<body style="margin:0;background:#2a2a33;display:flex;justify-content:center;padding-top:12px">
      <img src="${img(n)}" style="height:740px;box-shadow:0 4px 30px #000"></body>`);
    await caption(`Page ${n} of ${pngs.length} · ${text}`, ms);
  };

  await show(1, "Cover: the disclaimer box sits under the rating. The rating summary now prints in full (it used to stop after one line).", 5200);
  await show(find("Not asked by this tool"), "Fields the questionnaire never asks now say 'Not asked by this tool. Fill in by hand.' They used to say 'Not disclosed'.", 5200);
  await show(find("Pre-Deployment Checklist"), "Checklist: things the tool never asks get a ? and a note, not a red fail mark. Marks are drawn now; they used to print as garbage characters.", 5200);
  await show(pngs.length, "Every page has the short disclaimer line at the bottom, above the page number.", 4200);
  await caption(errors.length ? `Page errors: ${errors.join(" | ")}` : "Done. No page errors.", 2500);

  await ctx.close();
  await browser.close();

  const list = path.join(out, "frames.txt");
  fs.writeFileSync(list, frames.map(f => `file '${f.shot}'\nduration ${f.sec}`).join("\n") + `\nfile '${frames.at(-1).shot}'\n`);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", list,
    "-vf", "fps=10,format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", path.join(out, "vpg-replay.mp4")]);
  console.log(JSON.stringify({ pdf: file, pages: pngs.length, errors }));
})();
